
create extension if not exists btree_gist with schema extensions;
create table public.practice_location(id uuid primary key default gen_random_uuid(),practice_id uuid not null references public.practice(id) on delete cascade,name text not null,location_type text not null default 'consulting_room' check(location_type in('practice','consulting_room','procedure_room','telehealth','other')),address jsonb not null default '{}'::jsonb,timezone text not null default 'Africa/Johannesburg',active boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(practice_id,name));
create table public.practitioner_profile(id uuid primary key default gen_random_uuid(),practice_id uuid not null references public.practice(id) on delete cascade,user_id uuid,display_name text not null,profession text,speciality text,hpcsa_number text,practice_number text,billing_provider_number text,default_location_id uuid references public.practice_location(id) on delete set null,active boolean not null default true,metadata jsonb not null default '{}'::jsonb,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint practitioner_profile_user_membership_fk foreign key(practice_id,user_id) references public.practice_staff_member(practice_id,user_id) on delete restrict,unique(practice_id,user_id));
create unique index practitioner_profile_hpcsa_uq on public.practitioner_profile(practice_id,hpcsa_number) where hpcsa_number is not null;
create unique index practitioner_profile_practice_number_uq on public.practitioner_profile(practice_id,practice_number) where practice_number is not null;
create table public.appointment_type(id uuid primary key default gen_random_uuid(),practice_id uuid not null references public.practice(id) on delete cascade,name text not null,duration_minutes integer not null default 30 check(duration_minutes between 5 and 480),encounter_type text not null default 'consultation' check(encounter_type in('consultation','procedure','follow_up','telehealth','hospital','other')),colour_key text,active boolean not null default true,requires_authorisation boolean not null default false,metadata jsonb not null default '{}'::jsonb,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(practice_id,name));
create table public.practitioner_availability_rule(id uuid primary key default gen_random_uuid(),practice_id uuid not null references public.practice(id) on delete cascade,practitioner_id uuid not null references public.practitioner_profile(id) on delete cascade,location_id uuid references public.practice_location(id) on delete set null,day_of_week smallint not null check(day_of_week between 0 and 6),start_time time not null,end_time time not null,effective_from date,effective_to date,active boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(end_time>start_time),check(effective_to is null or effective_from is null or effective_to>=effective_from));
create table public.practitioner_schedule_exception(id uuid primary key default gen_random_uuid(),practice_id uuid not null references public.practice(id) on delete cascade,practitioner_id uuid not null references public.practitioner_profile(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,exception_type text not null check(exception_type in('unavailable','available_override')),reason text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.appointment_sequence(practice_id uuid not null references public.practice(id) on delete cascade,calendar_year integer not null,last_value bigint not null default 0,primary key(practice_id,calendar_year));
create table public.practice_appointment(id uuid primary key default gen_random_uuid(),practice_id uuid not null references public.practice(id) on delete cascade,appointment_number text not null,patient_id uuid not null references public.crm_patient(id) on delete restrict,practitioner_id uuid not null references public.practitioner_profile(id) on delete restrict,appointment_type_id uuid not null references public.appointment_type(id) on delete restrict,location_id uuid references public.practice_location(id) on delete set null,appointment_request_id uuid references public.appointment_request(id) on delete set null,encounter_id uuid references public.practice_encounter(id) on delete set null,starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'booked' check(status in('booked','confirmed','checked_in','in_progress','completed','cancelled','no_show')),booking_source text not null default 'internal' check(booking_source in('internal','request','phone','email','whatsapp','walk_in','portal','import','other')),reason text,notes text,cancellation_reason text,checked_in_at timestamptz,started_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,created_by uuid not null references auth.users(id) on delete restrict,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at),unique(practice_id,appointment_number),unique(encounter_id));
alter table public.practice_appointment add constraint practice_appointment_practitioner_no_overlap exclude using gist(practitioner_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(status in('booked','confirmed','checked_in','in_progress'));
alter table public.practice_appointment add constraint practice_appointment_location_no_overlap exclude using gist(location_id with =,tstzrange(starts_at,ends_at,'[)') with &&) where(location_id is not null and status in('booked','confirmed','checked_in','in_progress'));
create table public.appointment_event(id uuid primary key default gen_random_uuid(),appointment_id uuid not null references public.practice_appointment(id) on delete cascade,event_type text not null,actor_user_id uuid references auth.users(id) on delete set null,from_status text,to_status text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.appointment_waitlist(id uuid primary key default gen_random_uuid(),practice_id uuid not null references public.practice(id) on delete cascade,patient_id uuid not null references public.crm_patient(id) on delete cascade,appointment_type_id uuid references public.appointment_type(id) on delete set null,practitioner_id uuid references public.practitioner_profile(id) on delete set null,preferred_from date,preferred_to date,preferred_dayparts text[] not null default '{}'::text[],priority smallint not null default 3 check(priority between 1 and 5),status text not null default 'waiting' check(status in('waiting','offered','booked','closed')),notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(preferred_to is null or preferred_from is null or preferred_to>=preferred_from));
create index practice_location_practice_idx on public.practice_location(practice_id,active);
create index practitioner_profile_practice_idx on public.practitioner_profile(practice_id,active);
create index appointment_type_practice_idx on public.appointment_type(practice_id,active);
create index practitioner_availability_practitioner_idx on public.practitioner_availability_rule(practitioner_id,day_of_week,active);
create index practitioner_schedule_exception_practitioner_idx on public.practitioner_schedule_exception(practitioner_id,starts_at,ends_at);
create index practice_appointment_practice_start_idx on public.practice_appointment(practice_id,starts_at);
create index practice_appointment_patient_idx on public.practice_appointment(patient_id,starts_at desc);
create index practice_appointment_request_idx on public.practice_appointment(appointment_request_id) where appointment_request_id is not null;
create index appointment_event_appointment_idx on public.appointment_event(appointment_id,created_at);
create index appointment_waitlist_practice_idx on public.appointment_waitlist(practice_id,status,priority,created_at);
create trigger practice_appointment_patient_tenant_guard before insert or update of practice_id,patient_id on public.practice_appointment for each row execute function public.enforce_same_practice_reference('crm_patient','patient_id');
create trigger practice_appointment_practitioner_tenant_guard before insert or update of practice_id,practitioner_id on public.practice_appointment for each row execute function public.enforce_same_practice_reference('practitioner_profile','practitioner_id');
create trigger practice_appointment_type_tenant_guard before insert or update of practice_id,appointment_type_id on public.practice_appointment for each row execute function public.enforce_same_practice_reference('appointment_type','appointment_type_id');
create trigger practice_appointment_location_tenant_guard before insert or update of practice_id,location_id on public.practice_appointment for each row execute function public.enforce_same_practice_reference('practice_location','location_id');
create trigger practice_appointment_request_tenant_guard before insert or update of practice_id,appointment_request_id on public.practice_appointment for each row execute function public.enforce_same_practice_reference('appointment_request','appointment_request_id');
create trigger practice_appointment_encounter_tenant_guard before insert or update of practice_id,encounter_id on public.practice_appointment for each row execute function public.enforce_same_practice_reference('practice_encounter','encounter_id');
create trigger practitioner_profile_location_tenant_guard before insert or update of practice_id,default_location_id on public.practitioner_profile for each row execute function public.enforce_same_practice_reference('practice_location','default_location_id');
create trigger practitioner_availability_practitioner_tenant_guard before insert or update of practice_id,practitioner_id on public.practitioner_availability_rule for each row execute function public.enforce_same_practice_reference('practitioner_profile','practitioner_id');
create trigger practitioner_availability_location_tenant_guard before insert or update of practice_id,location_id on public.practitioner_availability_rule for each row execute function public.enforce_same_practice_reference('practice_location','location_id');
create trigger practitioner_exception_tenant_guard before insert or update of practice_id,practitioner_id on public.practitioner_schedule_exception for each row execute function public.enforce_same_practice_reference('practitioner_profile','practitioner_id');
create trigger appointment_waitlist_patient_tenant_guard before insert or update of practice_id,patient_id on public.appointment_waitlist for each row execute function public.enforce_same_practice_reference('crm_patient','patient_id');
create trigger appointment_waitlist_type_tenant_guard before insert or update of practice_id,appointment_type_id on public.appointment_waitlist for each row execute function public.enforce_same_practice_reference('appointment_type','appointment_type_id');
create trigger appointment_waitlist_practitioner_tenant_guard before insert or update of practice_id,practitioner_id on public.appointment_waitlist for each row execute function public.enforce_same_practice_reference('practitioner_profile','practitioner_id');
alter table public.practice_location enable row level security; alter table public.practitioner_profile enable row level security; alter table public.appointment_type enable row level security; alter table public.practitioner_availability_rule enable row level security; alter table public.practitioner_schedule_exception enable row level security; alter table public.appointment_sequence enable row level security; alter table public.practice_appointment enable row level security; alter table public.appointment_event enable row level security; alter table public.appointment_waitlist enable row level security;
create policy practice_location_staff_read on public.practice_location for select to authenticated using(exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_location.practice_id and m.active));
create policy practitioner_profile_staff_read on public.practitioner_profile for select to authenticated using(exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_profile.practice_id and m.active));
create policy appointment_type_staff_read on public.appointment_type for select to authenticated using(exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_type.practice_id and m.active));
create policy practitioner_availability_staff_read on public.practitioner_availability_rule for select to authenticated using(exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_availability_rule.practice_id and m.active));
create policy practitioner_schedule_exception_staff_read on public.practitioner_schedule_exception for select to authenticated using(exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_schedule_exception.practice_id and m.active));
create policy practice_appointment_staff_read on public.practice_appointment for select to authenticated using(exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_appointment.practice_id and m.active));
create policy appointment_event_staff_read on public.appointment_event for select to authenticated using(exists(select 1 from public.practice_appointment a join public.practice_staff_member m on m.practice_id=a.practice_id where a.id=appointment_event.appointment_id and m.user_id=(select auth.uid()) and m.active));
create policy appointment_waitlist_staff_read on public.appointment_waitlist for select to authenticated using(exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_waitlist.practice_id and m.active));
create policy practice_location_manage on public.practice_location for all to authenticated using(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_location.practice_id and m.active and m.role in('practice_manager','system_admin'))) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_location.practice_id and m.active and m.role in('practice_manager','system_admin')));
create policy practitioner_profile_manage on public.practitioner_profile for all to authenticated using(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_profile.practice_id and m.active and m.role in('practice_manager','system_admin'))) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_profile.practice_id and m.active and m.role in('practice_manager','system_admin')));
create policy appointment_type_manage on public.appointment_type for all to authenticated using(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_type.practice_id and m.active and m.role in('practice_manager','clinical_admin','system_admin'))) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_type.practice_id and m.active and m.role in('practice_manager','clinical_admin','system_admin')));
create policy practitioner_availability_manage on public.practitioner_availability_rule for all to authenticated using(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_availability_rule.practice_id and m.active and m.role in('practice_manager','clinical_admin','system_admin'))) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_availability_rule.practice_id and m.active and m.role in('practice_manager','clinical_admin','system_admin')));
create policy practitioner_schedule_exception_manage on public.practitioner_schedule_exception for all to authenticated using(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_schedule_exception.practice_id and m.active and m.role in('practice_manager','clinical_admin','system_admin'))) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practitioner_schedule_exception.practice_id and m.active and m.role in('practice_manager','clinical_admin','system_admin')));
create policy appointment_waitlist_manage on public.appointment_waitlist for all to authenticated using(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_waitlist.practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin'))) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_waitlist.practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin')));
create policy practice_appointment_rpc_insert on public.practice_appointment for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and (select coalesce(current_setting('request.path',true),'')) in('/rpc/create_practice_appointment') and created_by=(select auth.uid()) and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_appointment.practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin')));
create policy practice_appointment_rpc_update on public.practice_appointment for update to authenticated using(((select auth.jwt())->>'aal')='aal2' and (select coalesce(current_setting('request.path',true),'')) in('/rpc/reschedule_practice_appointment','/rpc/update_practice_appointment_status') and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_appointment.practice_id and m.active)) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_appointment.practice_id and m.active));
create policy appointment_event_rpc_insert on public.appointment_event for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and (select coalesce(current_setting('request.path',true),'')) in('/rpc/create_practice_appointment','/rpc/reschedule_practice_appointment','/rpc/update_practice_appointment_status') and actor_user_id=(select auth.uid()) and exists(select 1 from public.practice_appointment a join public.practice_staff_member m on m.practice_id=a.practice_id where a.id=appointment_event.appointment_id and m.user_id=(select auth.uid()) and m.active));
create policy appointment_request_booking_event_insert on public.appointment_request_event for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and (select coalesce(current_setting('request.path',true),''))='/rpc/create_practice_appointment' and actor_user_id=(select auth.uid()) and exists(select 1 from public.appointment_request r join public.practice_staff_member m on m.practice_id=r.practice_id where r.id=appointment_request_event.appointment_request_id and m.user_id=(select auth.uid()) and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin')));
create or replace function public.next_appointment_number(p_practice_id uuid,p_date date default current_date) returns text language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_year int:=extract(year from coalesce(p_date,current_date)); v_value bigint; begin insert into public.appointment_sequence(practice_id,calendar_year,last_value) values(p_practice_id,v_year,1) on conflict(practice_id,calendar_year) do update set last_value=public.appointment_sequence.last_value+1 returning last_value into v_value; return 'APT-'||v_year::text||'-'||lpad(v_value::text,6,'0'); end $$;
create policy appointment_sequence_rpc_insert on public.appointment_sequence for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and (select coalesce(current_setting('request.path',true),''))='/rpc/create_practice_appointment' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_sequence.practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin')));
create policy appointment_sequence_rpc_update on public.appointment_sequence for update to authenticated using(((select auth.jwt())->>'aal')='aal2' and (select coalesce(current_setting('request.path',true),''))='/rpc/create_practice_appointment' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_sequence.practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin'))) with check(true);
create or replace function public.create_practice_appointment(p_practice_id uuid,p_patient_id uuid,p_practitioner_id uuid,p_appointment_type_id uuid,p_starts_at timestamptz,p_location_id uuid default null,p_booking_source text default 'internal',p_reason text default null,p_notes text default null,p_appointment_request_id uuid default null) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_user uuid:=(select auth.uid()); v_type public.appointment_type%rowtype; v_id uuid:=gen_random_uuid(); v_end timestamptz; v_number text; v_request_status text; begin if v_user is null then raise exception 'Authentication required'; end if; if coalesce((select auth.jwt()->>'aal'),'')<>'aal2' then raise exception 'MFA assurance level 2 required'; end if; if not exists(select 1 from public.practice_staff_member m where m.user_id=v_user and m.practice_id=p_practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin')) then raise exception 'Appointment scheduling role required'; end if; if not exists(select 1 from public.crm_patient p where p.id=p_patient_id and p.practice_id=p_practice_id and p.status='active') then raise exception 'Active patient not found in selected practice'; end if; if not exists(select 1 from public.practitioner_profile p where p.id=p_practitioner_id and p.practice_id=p_practice_id and p.active) then raise exception 'Active practitioner not found in selected practice'; end if; select * into v_type from public.appointment_type where id=p_appointment_type_id and practice_id=p_practice_id and active; if not found then raise exception 'Active appointment type not found in selected practice'; end if; if p_starts_at<now()-interval '1 day' then raise exception 'Appointment start is too far in the past'; end if; v_end:=p_starts_at+make_interval(mins=>v_type.duration_minutes); if exists(select 1 from public.practitioner_schedule_exception e where e.practice_id=p_practice_id and e.practitioner_id=p_practitioner_id and e.exception_type='unavailable' and tstzrange(e.starts_at,e.ends_at,'[)')&&tstzrange(p_starts_at,v_end,'[)')) then raise exception 'Practitioner is unavailable during the requested time'; end if; v_number:=public.next_appointment_number(p_practice_id,p_starts_at::date); insert into public.practice_appointment(id,practice_id,appointment_number,patient_id,practitioner_id,appointment_type_id,location_id,appointment_request_id,starts_at,ends_at,booking_source,reason,notes,created_by,updated_by) values(v_id,p_practice_id,v_number,p_patient_id,p_practitioner_id,p_appointment_type_id,p_location_id,p_appointment_request_id,p_starts_at,v_end,p_booking_source,p_reason,p_notes,v_user,v_user); insert into public.appointment_event(appointment_id,event_type,actor_user_id,to_status,metadata) values(v_id,'created',v_user,'booked',jsonb_build_object('appointment_number',v_number,'starts_at',p_starts_at,'ends_at',v_end)); if p_appointment_request_id is not null then select status into v_request_status from public.appointment_request where id=p_appointment_request_id and practice_id=p_practice_id for update; if not found then raise exception 'Appointment request not found in selected practice'; end if; update public.appointment_request set patient_id=coalesce(patient_id,p_patient_id),status='Booked in PracticeCtrl',confirmed_at=coalesce(confirmed_at,now()),closed_at=coalesce(closed_at,now()),updated_at=now() where id=p_appointment_request_id; insert into public.appointment_request_event(appointment_request_id,event_type,actor_user_id,from_status,to_status,metadata) values(p_appointment_request_id,'booking_created',v_user,v_request_status,'Booked in PracticeCtrl',jsonb_build_object('appointment_id',v_id,'appointment_number',v_number)); end if; return v_id; exception when exclusion_violation then raise exception 'The practitioner or room is already booked during this time'; end $$;
create or replace function public.reschedule_practice_appointment(p_appointment_id uuid,p_starts_at timestamptz,p_location_id uuid default null,p_reason text default null) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_user uuid:=(select auth.uid()); v_a public.practice_appointment%rowtype; v_type public.appointment_type%rowtype; v_end timestamptz; begin if v_user is null or coalesce((select auth.jwt()->>'aal'),'')<>'aal2' then raise exception 'AAL2 authentication required'; end if; select * into v_a from public.practice_appointment where id=p_appointment_id for update; if not found then raise exception 'Appointment not found'; end if; if v_a.status not in('booked','confirmed') then raise exception 'Only booked or confirmed appointments may be rescheduled'; end if; if not exists(select 1 from public.practice_staff_member m where m.user_id=v_user and m.practice_id=v_a.practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin')) then raise exception 'Appointment scheduling role required'; end if; select * into v_type from public.appointment_type where id=v_a.appointment_type_id; v_end:=p_starts_at+make_interval(mins=>v_type.duration_minutes); if exists(select 1 from public.practitioner_schedule_exception e where e.practice_id=v_a.practice_id and e.practitioner_id=v_a.practitioner_id and e.exception_type='unavailable' and tstzrange(e.starts_at,e.ends_at,'[)')&&tstzrange(p_starts_at,v_end,'[)')) then raise exception 'Practitioner is unavailable during the requested time'; end if; update public.practice_appointment set starts_at=p_starts_at,ends_at=v_end,location_id=coalesce(p_location_id,location_id),updated_by=v_user,updated_at=now() where id=p_appointment_id; insert into public.appointment_event(appointment_id,event_type,actor_user_id,from_status,to_status,metadata) values(p_appointment_id,'rescheduled',v_user,v_a.status,v_a.status,jsonb_build_object('from_starts_at',v_a.starts_at,'to_starts_at',p_starts_at,'reason',p_reason)); return p_appointment_id; exception when exclusion_violation then raise exception 'The practitioner or room is already booked during this time'; end $$;
create or replace function public.update_practice_appointment_status(p_appointment_id uuid,p_status text,p_reason text default null) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_user uuid:=(select auth.uid()); v_a public.practice_appointment%rowtype; v_practitioner_user uuid; v_encounter uuid; v_allowed boolean:=false; begin if v_user is null or coalesce((select auth.jwt()->>'aal'),'')<>'aal2' then raise exception 'AAL2 authentication required'; end if; select * into v_a from public.practice_appointment where id=p_appointment_id for update; if not found then raise exception 'Appointment not found'; end if; select user_id into v_practitioner_user from public.practitioner_profile where id=v_a.practitioner_id; if exists(select 1 from public.practice_staff_member m where m.user_id=v_user and m.practice_id=v_a.practice_id and m.active and m.role in('practice_manager','clinical_admin','system_admin')) then v_allowed:=true; end if; if exists(select 1 from public.practice_staff_member m where m.user_id=v_user and m.practice_id=v_a.practice_id and m.active and m.role='reception') and p_status in('confirmed','checked_in','cancelled','no_show') then v_allowed:=true; end if; if v_practitioner_user=v_user and p_status in('in_progress','completed') then v_allowed:=true; end if; if not v_allowed then raise exception 'Appointment workflow role required'; end if; if not((v_a.status='booked' and p_status in('confirmed','checked_in','cancelled','no_show')) or(v_a.status='confirmed' and p_status in('checked_in','cancelled','no_show')) or(v_a.status='checked_in' and p_status in('in_progress','cancelled')) or(v_a.status='in_progress' and p_status='completed')) then raise exception 'Invalid appointment status transition: % → %',v_a.status,p_status; end if; if p_status='cancelled' and nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Cancellation reason is required'; end if; if p_status='in_progress' and v_a.encounter_id is null then insert into public.practice_encounter(practice_id,patient_id,practitioner_user_id,service_date,encounter_type,status,source_system,source_reference,created_by) select v_a.practice_id,v_a.patient_id,v_practitioner_user,(v_a.starts_at at time zone coalesce(p.timezone,'Africa/Johannesburg'))::date,t.encounter_type,'open','PracticeCtrl Appointment',v_a.id::text,v_user from public.practice p join public.appointment_type t on t.id=v_a.appointment_type_id where p.id=v_a.practice_id returning id into v_encounter; else v_encounter:=v_a.encounter_id; end if; update public.practice_appointment set status=p_status,encounter_id=coalesce(v_encounter,encounter_id),checked_in_at=case when p_status='checked_in' then now() else checked_in_at end,started_at=case when p_status='in_progress' then now() else started_at end,completed_at=case when p_status='completed' then now() else completed_at end,cancelled_at=case when p_status='cancelled' then now() else cancelled_at end,cancellation_reason=case when p_status='cancelled' then p_reason else cancellation_reason end,updated_by=v_user,updated_at=now() where id=p_appointment_id; if p_status='completed' and v_encounter is not null then update public.practice_encounter set status='completed',completed_at=coalesce(completed_at,now()),updated_at=now() where id=v_encounter; end if; insert into public.appointment_event(appointment_id,event_type,actor_user_id,from_status,to_status,metadata) values(p_appointment_id,'status_changed',v_user,v_a.status,p_status,jsonb_build_object('reason',p_reason,'encounter_id',v_encounter)); return p_appointment_id; end $$;
alter table public.appointment_request drop constraint appointment_request_status_check;
alter table public.appointment_request add constraint appointment_request_status_check check(status=any(array['New','Contacted','Confirmed in PMS','Booked in PracticeCtrl','Alternative Offered','Unable to Reach','Closed','Duplicate']));
insert into public.platform_module(module_key,display_name,descriptor,flagship,enabled_by_default,ai_enabled,voice_enabled,status) values('appointments','Appointments & Diary','Practitioner calendars, booking, check-in, appointment flow, waitlist and encounter handoff',false,true,true,true,'development') on conflict(module_key) do update set display_name=excluded.display_name,descriptor=excluded.descriptor,enabled_by_default=true,ai_enabled=true,voice_enabled=true,status='development';
revoke all on function public.next_appointment_number(uuid,date) from public,anon;
revoke all on function public.create_practice_appointment(uuid,uuid,uuid,uuid,timestamptz,uuid,text,text,text,uuid) from public,anon;
revoke all on function public.reschedule_practice_appointment(uuid,timestamptz,uuid,text) from public,anon;
revoke all on function public.update_practice_appointment_status(uuid,text,text) from public,anon;
grant execute on function public.next_appointment_number(uuid,date) to authenticated;
grant execute on function public.create_practice_appointment(uuid,uuid,uuid,uuid,timestamptz,uuid,text,text,text,uuid) to authenticated;
grant execute on function public.reschedule_practice_appointment(uuid,timestamptz,uuid,text) to authenticated;
grant execute on function public.update_practice_appointment_status(uuid,text,text) to authenticated;
grant select,insert,update,delete on public.practice_location,public.practitioner_profile,public.appointment_type,public.practitioner_availability_rule,public.practitioner_schedule_exception,public.appointment_waitlist to authenticated;
grant select,insert,update on public.practice_appointment to authenticated;
grant select,insert on public.appointment_event to authenticated;
grant select,insert,update on public.appointment_sequence to authenticated;

